    async renderArtwork(format='png'){
      const doc=withSources(this.document(),[...this.sources.values()]);await this.loadFonts(doc);
      const out=new this.F.StaticCanvas(documentElement('canvas'),{width:this.board.width,height:this.board.height,enableRetinaScaling:false});
      try{await out.loadFromJSON(doc);out.setViewportTransform([1,0,0,1,0,0]);out.renderAll();return out.toDataURL({format,quality:1,multiplier:1,enableRetinaScaling:false}).split(',')[1];}finally{await out.dispose();}
    }
    async refreshSavedDesigns(older=false){
      const r=await this.request('adDesignSavedDesigns',{...this.input(),...(older&&this.savedDesignCursor?{before:this.savedDesignCursor}:{})});
      this.savedCopies=older?[...(this.savedCopies||[]),...(r.savedDesigns||[])]:r.savedDesigns||[];this.savedDesignCursor=r.savedDesignCursor||null;
      this.options.savedDesignsChanged?.(this.savedCopies,this.savedDesignCursor);if(this.tab==='photos')this.renderLeft();return r;
    }
